using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values
        // and DateTime.UtcNow is non-deterministic (already problematic, unchanged here).
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // For existing documents that already store "Discriminator", explicitly
            // configure the old property name to maintain backward compatibility.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// EF Core 9 breaking change #2: Synchronous I/O on Cosmos DB now throws by default.
// All queries/saves must use async APIs (ToListAsync, SaveChangesAsync, etc.).
class CosmosQueryService
{
    // WRONG in EF Core 9 (throws InvalidOperationException):
    // var items = db.Products.ToList();

    // CORRECT — use async:
    public async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
        => await db.Products.ToListAsync();
}

